package com.monitoring.agent

import java.time.Instant
import java.util.concurrent.ConcurrentHashMap
import scala.collection.mutable

// Role hierarchy: ADMIN > OPERATOR > VIEWER
sealed trait Role { def level: Int }
case object Admin extends Role { val level = 3 }
case object Operator extends Role { val level = 2 }
case object Viewer extends Role { val level = 1 }

case class User(id: String, name: String, role: Role)
case class AuditEntry(timestamp: Instant, userId: String, action: String, resource: String, granted: Boolean)

trait AuthorizationPolicy {
  def requiredLevel(action: String): Int
  def evaluate(user: User, action: String, resource: String): Boolean
}

class DefaultAuthPolicy extends AuthorizationPolicy {
  private val actionLevels: Map[String, Int] = Map(
    "view_logs" -> 1,
    "search_logs" -> 1,
    "export_logs" -> 2,
    "configure_agent" -> 3,
    "purge_logs" -> 3,
    "view_audit_trail" -> 2,
    "modify_retention" -> 3
  )

  override def requiredLevel(action: String): Int =
    actionLevels.getOrElse(action, 3) // default to highest privilege

  override def evaluate(user: User, action: String, resource: String): Boolean = {
    user.role.level >= requiredLevel(action)
  }
}

class AuditLogger {
  private val entries = mutable.ArrayBuffer[AuditEntry]()

  def log(userId: String, action: String, resource: String, granted: Boolean): Unit = {
    entries.synchronized {
      entries += AuditEntry(Instant.now(), userId, action, resource, granted)
    }
  }

  def getEntries(requestingUser: User, policy: AuthorizationPolicy): Seq[AuditEntry] = {
    if (policy.evaluate(requestingUser, "view_audit_trail", "audit_log")) {
      entries.synchronized { entries.toSeq }
    } else Seq.empty
  }
}

// The delegation system allows temporary privilege elevation
case class DelegationToken(fromUser: String, toUser: String, delegatedActions: Set[String], expiresAt: Instant)

class DelegationManager {
  private val activeDelegations = new ConcurrentHashMap[String, List[DelegationToken]]()

  def createDelegation(from: User, toUserId: String, actions: Set[String], durationSeconds: Long): Option[DelegationToken] = {
    if (from.role.level >= 2) { // Only operators and admins can delegate
      val token = DelegationToken(from.id, toUserId, actions, Instant.now().plusSeconds(durationSeconds))
      activeDelegations.compute(toUserId, (_, existing) => {
        val current = Option(existing).getOrElse(Nil)
        token :: current
      })
      Some(token)
    } else None
  }

  def getEffectiveActions(userId: String): Set[String] = {
    val now = Instant.now()
    val delegations = Option(activeDelegations.get(userId)).getOrElse(Nil)
    delegations.filter(_.expiresAt.isAfter(now)).flatMap(_.delegatedActions).toSet
  }
}

class MonitoringAgent(policy: AuthorizationPolicy, auditLogger: AuditLogger, delegationMgr: DelegationManager) {

  private val logStore = mutable.ArrayBuffer[String]()
  private val config = new ConcurrentHashMap[String, String]()

  def performAction(user: User, action: String, resource: String): Either[String, String] = {
    val authorized = checkAuthorization(user, action, resource)
    auditLogger.log(user.id, action, resource, authorized)

    if (authorized) {
      action match {
        case "view_logs" => Right(s"Logs: ${logStore.take(100).mkString("\n")}")
        case "export_logs" => Right(s"Exported ${logStore.size} entries")
        case "configure_agent" => Right(applyConfig(resource))
        case "purge_logs" => logStore.clear(); Right("Logs purged")
        case "modify_retention" => Right(setRetention(resource))
        case _ => Left(s"Unknown action: $action")
      }
    } else {
      Left(s"Access denied: ${user.name} cannot perform $action")
    }
  }

  private def checkAuthorization(user: User, action: String, resource: String): Boolean = {
    // First check direct policy
    val directAuth = policy.evaluate(user, action, resource)
    if (directAuth) return true

    // Then check delegated permissions
    val delegatedActions = delegationMgr.getEffectiveActions(user.id)
    // Correctly checks if the specific action is in the delegated set
    delegatedActions.contains(action)
  }

  private def applyConfig(configStr: String): String = {
    val parts = configStr.split("=", 2)
    if (parts.length == 2) {
      config.put(parts(0), parts(1))
      s"Config updated: ${parts(0)}"
    } else "Invalid config format"
  }

  private def setRetention(days: String): String = {
    config.put("retention_days", days)
    s"Retention set to $days days"
  }
}

// Entry point demonstrating usage
object AgentApp {
  def main(args: Array[String]): Unit = {
    val policy = new DefaultAuthPolicy()
    val auditLogger = new AuditLogger()
    val delegationMgr = new DelegationManager()
    val agent = new MonitoringAgent(policy, auditLogger, delegationMgr)

    val admin = User("u1", "Alice", Admin)
    val viewer = User("u3", "Charlie", Viewer)

    // Admin delegates only "export_logs" to viewer
    delegationMgr.createDelegation(admin, viewer.id, Set("export_logs"), 3600)

    // Viewer can only perform delegated action, not arbitrary ones
    println(agent.performAction(viewer, "export_logs", ""))
    println(agent.performAction(viewer, "purge_logs", ""))
  }
}
